effect.shader:
// Utility random and value noise
float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

float valueNoise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Fractal Brownian Motion (FBM)
float fbm(vec2 p, float oct, float lac, float g) {
    float sum = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    for (float i = 0.0; i < 8.0; i += 1.0) {
        if (i >= oct) break;
        sum += amp * valueNoise(p * freq);
        freq *= lac;
        amp *= g;
    }
    return sum;
}

// Curl noise from fbm via finite differences
vec2 curl(vec2 p, float oct, float lac, float g) {
    float eps = 0.001;
    float n1 = fbm(p + vec2(0.0, eps), oct, lac, g);
    float n2 = fbm(p - vec2(0.0, eps), oct, lac, g);
    float n3 = fbm(p + vec2(eps, 0.0), oct, lac, g);
    float n4 = fbm(p - vec2(eps, 0.0), oct, lac, g);
    float dx = (n3 - n4) / (2.0 * eps);
    float dy = (n1 - n2) / (2.0 * eps);
    return vec2(dy, -dx); // 2D curl
}

vec2 wrapUV(vec2 uv) {
    if (wrapMode == 1) {
        // Repeat
        return fract(uv);
    } else if (wrapMode == 2) {
        // Mirror
        vec2 wrapped = fract(uv);
        vec2 mirror = step(0.5, fract(uv * 0.5));
        return mix(wrapped, 1.0 - wrapped, mirror);
    } else {
        // Clamp
        return clamp(uv, vec2(0.0), vec2(1.0));
    }
}

void main() {
    vec2 uv = acScreenNorm.xy;

    // Time-evolved coordinate
    float t = evolution + acTime * evolutionSpeed + seed * 0.1234;
    vec2 baseP = uv * scale + vec2(t);

    // Domain warp for richer structures
    vec2 warpVec;
    float nA = fbm(baseP + vec2(13.1, 7.3), octaves, lacunarity, gain);
    float nB = fbm(baseP + vec2(-9.7, 2.6), octaves, lacunarity, gain);
    warpVec = vec2(nA, nB) * warpAmount;

    vec2 p = baseP + warpVec * 2.0;
    vec2 disp;
    if (mode == 0) {
        // FBM vector displacement using two uncorrelated fields
        float nx = fbm(p + vec2(5.2, 1.3), octaves, lacunarity, gain);
        float ny = fbm(p + vec2(-3.1, 9.9), octaves, lacunarity, gain);
        disp = vec2(nx, ny) - 0.5; // Center around 0
    } else {
        // Flow-like curl noise field
        disp = curl(p, octaves, lacunarity, gain);
        // Curl is already centered around 0
    }

    // Apply axis strength and amount
    vec2 offset = disp * amount * vec2(xStrength, yStrength);
    vec2 sampleUV = wrapUV(uv + offset);

    vec4 color = texture2DCv(inputImg.texture, sampleUV);
    color.a *= alpha;
    gl_FragColor = color;
}
